-- mod-archaeology: the client patch's DBC rows, as the server needs them.
-- Generated by tools/build_patch.py from the same rows the client patch gets:
-- run the tool again, don't edit this file.

DELETE FROM `skillline_dbc` WHERE `ID` = 794;

DELETE FROM `skillraceclassinfo_dbc` WHERE `ID` = 90500;

DELETE FROM `skilllineability_dbc` WHERE `ID` BETWEEN 90500 AND 90506;

DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 90500 AND 90522;

DELETE FROM `item_dbc` WHERE `ID` BETWEEN 9504010 AND 9504012 OR `ID` BETWEEN 9504014 AND 9504017 OR `ID` BETWEEN 9504020 AND 9504073 OR `ID` BETWEEN 9504075 AND 9504079 OR `ID` BETWEEN 9504081 AND 9504092 OR `ID` BETWEEN 9504094 AND 9504104 OR `ID` BETWEEN 9504106 AND 9504126 OR `ID` BETWEEN 9504129 AND 9504139 OR `ID` BETWEEN 9504141 AND 9504145;

DELETE FROM `itemdisplayinfo_dbc` WHERE `ID` BETWEEN 950410 AND 950412 OR `ID` BETWEEN 950414 AND 950417 OR `ID` BETWEEN 950420 AND 950473 OR `ID` BETWEEN 950475 AND 950479 OR `ID` BETWEEN 950481 AND 950492 OR `ID` BETWEEN 950494 AND 950504 OR `ID` BETWEEN 950506 AND 950526 OR `ID` BETWEEN 950529 AND 950539 OR `ID` BETWEEN 950541 AND 950545 OR `ID` BETWEEN 950900 AND 950921;

