-- The core copies these from item_dbc anyway (DBC.EnforceItemAttributes); this keeps
-- item_template in step and the startup log quiet.
UPDATE `item_template` it JOIN `item_dbc` d ON d.`ID` = it.`entry`
SET it.`displayid` = d.`DisplayInfoID`, it.`Material` = d.`Material`
WHERE it.`entry` BETWEEN 9504000 AND 9504499;
